{
  "typography": {
    "fontFamily": "{font-sans}",
    "caption": {
      "fontSize": {
        "pointer": 12,
        "touch": 12
      },
      "lineHeight": {
        "pointer": 1.3333333333333333,
        "touch": 1.3333333333333333
      },
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "detail": {
      "fontSize": {
        "pointer": 12,
        "touch": 12
      },
      "lineHeight": {
        "pointer": 1.3333333333333333,
        "touch": 1.3333333333333333
      },
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "body": {
      "fontSize": {
        "pointer": 14,
        "touch": 14
      },
      "lineHeight": {
        "pointer": 1.4285714285714286,
        "touch": 1.4285714285714286
      },
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "label": {
      "fontSize": {
        "pointer": 14,
        "touch": 14
      },
      "lineHeight": {
        "pointer": 1.4285714285714286,
        "touch": 1.4285714285714286
      },
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "title": {
      "fontSize": {
        "pointer": 14,
        "touch": 14
      },
      "lineHeight": {
        "pointer": 1.4285714285714286,
        "touch": 1.4285714285714286
      },
      "fontWeight": 600,
      "letterSpacing": 0
    },
    "headline": {
      "fontSize": {
        "pointer": 20,
        "touch": 20
      },
      "lineHeight": {
        "pointer": 1.4,
        "touch": 1.4
      },
      "fontWeight": 600,
      "letterSpacing": 0
    },
    "display": {
      "fontSize": {
        "pointer": 28,
        "touch": 28
      },
      "lineHeight": {
        "pointer": 1.2857142857142858,
        "touch": 1.2857142857142858
      },
      "fontWeight": 600,
      "letterSpacing": 0
    }
  },
  "dimension": {
    "shape": {
      "control": "{radius-control}",
      "field": "{radius-field}",
      "chip": "{radius-chip}",
      "card": "{radius-card}",
      "overlay": "{radius-overlay}",
      "dialog": "{radius-dialog}",
      "sheet": "{radius-sheet}",
      "inset": "{radius}"
    },
    "size": {
      "hit": {
        "pointer": 0,
        "touch": 40
      },
      "density": {
        "pointer": {
          "row": 40,
          "pad": 16,
          "gap": 8,
          "surface": 4
        },
        "touch": {
          "row": 40,
          "pad": 16,
          "gap": 8,
          "surface": 8
        }
      },
      "control": {
        "pointer": {
          "row": 32,
          "padding": 6,
          "gap": 8,
          "control": 20,
          "corner": 4,
          "check": 12,
          "dot": 12,
          "tabs": 32,
          "line": 32,
          "clear": 16,
          "switch": "regular"
        },
        "touch": {
          "row": 40,
          "padding": 8,
          "gap": 8,
          "control": 20,
          "corner": 4,
          "check": 12,
          "dot": 12,
          "tabs": 40,
          "line": 40,
          "clear": 20,
          "switch": "regular"
        }
      },
      "height": {
        "pointer": {
          "sm": 24,
          "md": 32,
          "lg": 40
        },
        "touch": {
          "sm": 32,
          "md": 40,
          "lg": 48
        }
      }
    },
    "stroke": {
      "hairline": 1,
      "surface": 1,
      "control": 1,
      "indicator": 3
    },
    "focus": {
      "style": "double",
      "width": 2,
      "offset": 0
    },
    "icon": {
      "pointer": {
        "sm": 12,
        "md": 16,
        "lg": 20
      },
      "touch": {
        "sm": 16,
        "md": 20,
        "lg": 24
      }
    }
  },
  "shape": {
    "curve": "circular",
    "corners": {
      "field": "all"
    }
  },
  "state": {
    "press-scale": 1,
    "overlay": {
      "hover": 0,
      "focus": 0,
      "pressed": 0,
      "dragged": 0
    },
    "ripple": false,
    "pressed-opacity": 1,
    "disabled": {
      "content": 0.36,
      "container": 0.45
    }
  },
  "duration": {
    "shake": 500
  },
  "transition": {
    "enter": {
      "duration": 250,
      "timingFunction": "decelerate"
    }
  },
  "motion": {
    "press": {
      "duration": 83,
      "timingFunction": "decelerate"
    },
    "settle": {
      "duration": 250,
      "timingFunction": "decelerate"
    },
    "control": {
      "duration": 167,
      "timingFunction": "point-to-point"
    },
    "move": {
      "duration": 333,
      "timingFunction": "point-to-point"
    }
  },
  "indicator": {
    "tabs": "underline",
    "nav": "bar",
    "field": "underline"
  },
  "finishes": {
    "shared": {
      "card": {
        "gradient": "linear-gradient(180deg, {card} 0%, {card} 100%)",
        "material": null
      },
      "inset": {
        "material": null,
        "shadow": "none"
      },
      "field": {
        "shadow": "none",
        "material": null
      },
      "raised": {
        "background": "{raised}",
        "gradient": "linear-gradient(180deg, {raised} 0%, {raised} 100%)",
        "material": null,
        "border-color": "{border}"
      },
      "hover": {
        "material": null,
        "background": "{hover}",
        "gradient": "linear-gradient(180deg, {hover} 0%, {hover} 100%)",
        "border-color": "{border}"
      },
      "pressed": {
        "material": null,
        "background": "{muted}",
        "gradient": "linear-gradient(180deg, {muted} 0%, {muted} 100%)",
        "shadow": "none",
        "border-color": "{border}"
      },
      "light": {
        "background": "{primary}",
        "gradient": "linear-gradient(180deg, {primary} 0%, {primary} 100%)",
        "border-color": "{brand-edge}",
        "material": null,
        "shadow": "none"
      },
      "accent": {
        "background": "{primary}",
        "gradient": "linear-gradient(180deg, {primary} 0%, {primary} 100%)",
        "border-color": "{brand-edge}",
        "material": null,
        "shadow": "none"
      },
      "track": {
        "material": null,
        "shadow": "none",
        "border-color": "{input}"
      },
      "fill": {
        "background": "transparent",
        "shadow": "none",
        "material": null,
        "gradient": "linear-gradient(180deg, {primary} 0%, {primary} 100%)",
        "border-color": "transparent"
      },
      "knob": {
        "material": null,
        "background": "{knob}",
        "gradient": "linear-gradient(180deg, {knob} 0%, {knob} 100%)",
        "shadow": "none",
        "border-color": "transparent"
      },
      "knobOn": {
        "background": "{primary-foreground}",
        "gradient": "linear-gradient(180deg, {primary-foreground} 0%, {primary-foreground} 100%)",
        "shadow": "none",
        "material": null,
        "border-color": "transparent"
      },
      "handle": {
        "material": null,
        "background": "{popover}",
        "gradient": "linear-gradient(180deg, {popover} 0%, {popover} 100%)",
        "border-color": "{border}"
      },
      "pill": {
        "background": "{raised}",
        "gradient": "linear-gradient(180deg, {raised} 0%, {raised} 100%)",
        "material": null,
        "shadow": "none",
        "border-color": "{border}"
      },
      "thumb": {
        "material": null,
        "background": "{popover}",
        "gradient": "linear-gradient(180deg, {popover} 0%, {popover} 100%)",
        "border-color": "{border}"
      },
      "on": {
        "material": null,
        "background": "{brand-tint}",
        "gradient": "linear-gradient(180deg, {brand-tint} 0%, {brand-tint} 100%)",
        "shadow": "none",
        "border-color": "{border}"
      },
      "chip": {
        "background": "{raised}",
        "gradient": "linear-gradient(180deg, {raised} 0%, {raised} 100%)",
        "border-color": "{border}",
        "material": null,
        "shadow": "none"
      },
      "glass": {
        "border-color": "{glass-edge}",
        "backdropFilter": "blur(30px)",
        "material": {
          "windows": {
            "backdrop": "blur"
          }
        }
      },
      "menu": {
        "background": "{popover}",
        "border-color": "{glass-edge}",
        "material": {
          "windows": {
            "backdrop": "blur"
          }
        }
      },
      "dialog": {
        "background": "{background}",
        "material": null
      },
      "tooltip": {
        "background": "{popover}",
        "border-color": "{glass-edge}",
        "material": {
          "windows": {
            "backdrop": "blur"
          }
        }
      },
      "inverse": {
        "background": "{inverse}",
        "border-color": "{glass-edge}",
        "material": null
      },
      "groove": {
        "material": null,
        "shadow": "none"
      }
    },
    "light": {
      "card": {
        "shadow": "0 0 2px oklch(0 0 0 / 0.12), 0 4px 8px oklch(0 0 0 / 0.14)"
      },
      "raised": {
        "shadow": "0 0 2px oklch(0 0 0 / 0.12), 0 1px 2px oklch(0 0 0 / 0.14)"
      },
      "hover": {
        "shadow": "0 0 2px oklch(0 0 0 / 0.12), 0 1px 2px oklch(0 0 0 / 0.14)"
      },
      "handle": {
        "shadow": "0 0 2px oklch(0 0 0 / 0.12), 0 1px 2px oklch(0 0 0 / 0.14)"
      },
      "thumb": {
        "shadow": "0 0 2px oklch(0 0 0 / 0.12), 0 1px 2px oklch(0 0 0 / 0.14)"
      },
      "glass": {
        "background": "oklch(from {popover} l c h / 0.85)",
        "shadow": "0 0 8px oklch(0 0 0 / 0.2), 0 16px 32px oklch(0 0 0 / 0.24)"
      },
      "menu": {
        "shadow": "0 0 8px oklch(0 0 0 / 0.2), 0 16px 32px oklch(0 0 0 / 0.24)"
      },
      "dialog": {
        "border-color": "oklch(0.81093 0 0)",
        "shadow": "0 0 8px oklch(0 0 0 / 0.2), 0 64px 128px oklch(0 0 0 / 0.24)"
      },
      "tooltip": {
        "shadow": "0 0 2px oklch(0 0 0 / 0.12), 0 8px 16px oklch(0 0 0 / 0.14)"
      },
      "inverse": {
        "shadow": "0 0 8px oklch(0 0 0 / 0.2), 0 16px 32px oklch(0 0 0 / 0.24)"
      }
    },
    "dark": {
      "card": {
        "shadow": "0 0 2px oklch(0 0 0 / 0.24), 0 4px 8px oklch(0 0 0 / 0.28)"
      },
      "raised": {
        "shadow": "0 0 2px oklch(0 0 0 / 0.24), 0 1px 2px oklch(0 0 0 / 0.28)"
      },
      "hover": {
        "shadow": "0 0 2px oklch(0 0 0 / 0.24), 0 1px 2px oklch(0 0 0 / 0.28)"
      },
      "handle": {
        "shadow": "0 0 2px oklch(0 0 0 / 0.24), 0 1px 2px oklch(0 0 0 / 0.28)"
      },
      "thumb": {
        "shadow": "0 0 2px oklch(0 0 0 / 0.24), 0 1px 2px oklch(0 0 0 / 0.28)"
      },
      "glass": {
        "background": "oklch(from {popover} l c h / 0.96)",
        "shadow": "0 0 8px oklch(0 0 0 / 0.4), 0 16px 32px oklch(0 0 0 / 0.48)"
      },
      "menu": {
        "shadow": "0 0 8px oklch(0 0 0 / 0.4), 0 16px 32px oklch(0 0 0 / 0.48)"
      },
      "dialog": {
        "border-color": "oklch(0.37909 0 0)",
        "shadow": "0 0 8px oklch(0 0 0 / 0.4), 0 64px 128px oklch(0 0 0 / 0.48)"
      },
      "tooltip": {
        "shadow": "0 0 2px oklch(0 0 0 / 0.24), 0 8px 16px oklch(0 0 0 / 0.28)"
      },
      "inverse": {
        "shadow": "0 0 8px oklch(0 0 0 / 0.4), 0 16px 32px oklch(0 0 0 / 0.48)"
      }
    }
  }
}

{
  "$schema": "https://www.designtokens.org/schemas/2025.10/format.json",
  "$description": "WinUI 3 (light appearance, pointer tier) — standalone W3C DTCG 2025.10 tokens.",
  "cubicBezier": {
    "$type": "cubicBezier",
    "$description": "Named timing curves shared across themes.",
    "out-cubic": {
      "$value": [
        0.333333,
        1,
        0.666667,
        1
      ],
      "$description": "Exact cubic-bezier equivalent of NSH Easing.out(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "out-cubic"
        }
      }
    },
    "in-cubic": {
      "$value": [
        0.333333,
        0,
        0.666667,
        0
      ],
      "$description": "Exact cubic-bezier equivalent of NSH Easing.in(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "in-cubic"
        }
      }
    },
    "in-out-cubic": {
      "$value": [
        0.65,
        0,
        0.35,
        1
      ],
      "$description": "Cubic approximation of NSH Easing.inOut(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "in-out-cubic"
        }
      }
    },
    "standard": {
      "$value": [
        0.2,
        0,
        0,
        1
      ],
      "$description": "Material 3 md.sys.motion.easing.standard."
    },
    "emphasized-decelerate": {
      "$value": [
        0.05,
        0.7,
        0.1,
        1
      ],
      "$description": "Material 3 emphasized-decelerate curve."
    },
    "emphasized-accelerate": {
      "$value": [
        0.3,
        0,
        0.8,
        0.15
      ],
      "$description": "Material 3 emphasized-accelerate curve."
    },
    "decelerate": {
      "$value": [
        0,
        0,
        0,
        1
      ],
      "$description": "WinUI 3 / Fluent 2 Direct Entrance decelerate curve."
