  },
  "dimension": {
    "$type": "dimension",
    "$description": "Desktop pointer layout density, control geometry, and icon sizes.",
    "shape": {
      "$type": "dimension",
      "$description": "Semantic corner radius roles referencing base dimension.radius.* tokens.",
      "control": {
        "$value": "{dimension.radius.control}",
        "$description": "Corner radius for buttons, select triggers, tabs, and menu items."
      },
      "field": {
        "$value": "{dimension.radius.field}",
