      "card": {
        "$value": "{dimension.radius.card}",
        "$description": "Corner radius for cards and sidebar overlays."
      },
      "overlay": {
        "$value": "{dimension.radius.overlay}",
        "$description": "Corner radius for menus, popovers, and toasts."
      },
      "dialog": {
        "$value": "{dimension.radius.dialog}",
        "$description": "Corner radius for dialogs."
      },
      "sheet": {
        "$value": "{dimension.radius.sheet}",
        "$description": "Corner radius for drawers and bottom sheets."
      },
      "inset": {
        "$value": "{dimension.radius.base}",
        "$description": "Corner radius for inset wells, alerts, and skeletons inside cards."
      }
    },
    "stroke": {
      "$description": "Border and indicator stroke widths.",
      "hairline": {
        "$value": {
          "value": 1,
          "unit": "px"
        },
        "$description": "Hairline divider and outlined-variant stroke width."
