      },
      "card": {
        "$value": {
          "value": 8,
          "unit": "px"
        },
        "$description": "Corner radius for cards and sidebar floating containers."
      },
      "control": {
        "$value": {
          "value": 4,
          "unit": "px"
        },
        "$description": "Corner radius for interactive controls such as buttons, triggers, and menu items."
