      "overlay": {
        "$value": {
          "value": 8,
          "unit": "px"
        },
        "$description": "Corner radius for floating menus, popovers, and toasts."
      },
      "dialog": {
        "$value": {
          "value": 8,
          "unit": "px"
        },
        "$description": "Corner radius for modal dialogs."
      },
      "sheet": {
        "$value": {
          "value": 8,
          "unit": "px"
        },
        "$description": "Corner radius for drawers and bottom sheets."
